use std::io::{self,Write};use spore_core::{creature_skin_grid_retry_v1::{run,Admission,Gates},native_sse::Policy};
fn g(s:bool,m:bool,r:bool)->Gates{Gates{setup_ok:s,mesh_ok:m,retry_flag:r,grid_policy:Policy::Mxcsr1f80,retry_policy:Policy::Mxcsr1f80}}
fn main(){let cases=[([-1.;3],[1.;3],0.25,vec![g(true,false,true),g(true,true,false)]),([0.;3],[1.;3],0.1,vec![g(false,false,true)]),([0.;3],[1.;3],0.1,vec![g(true,false,false)]),([0.;3],[1.;3],0.5,vec![g(true,false,true)]),([-1.;3],[300.;3],1.,vec![g(true,true,false)])];let mut bytes=Vec::new();for (lo,hi,step,gates) in cases{let o=run(lo,hi,step,&gates,Admission).unwrap();let passed:Vec<_>=o.attempts.iter().filter(|x|x.grid_ok).collect();let mut words=vec![o.succeeded as u32,o.last_step.to_bits(),o.lower[0].to_bits(),o.lower[1].to_bits(),o.lower[2].to_bits(),passed.len() as u32];for x in passed{words.extend([x.step.to_bits(),x.lower_after[0].to_bits(),x.lower_after[1].to_bits(),x.lower_after[2].to_bits()]);}words.resize(18,0);for x in words{bytes.extend(x.to_le_bytes());}}io::stdout().write_all(&bytes).unwrap();}
